fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let r: i32 = 100;
    let cb: i32 = host::math::cos(20);
    let sb: i32 = host::math::sin(20);
    let mut lat: i32 = 0 - 56;
    while lat <= 56 {
        let ring: i32 = (r * host::math::cos(lat)) / 256;
        let y0: i32 = (r * host::math::sin(lat)) / 256;
        let mut lon: i32 = 0;
        while lon < 256 {
            let x0: i32 = (ring * host::math::cos(lon + t)) / 256;
            let z0: i32 = (ring * host::math::sin(lon + t)) / 256;
            let y1: i32 = (y0 * cb - z0 * sb) / 256;
            let z1: i32 = (y0 * sb + z0 * cb) / 256;
            let depth: i32 = z1 + 300;
            let px: i32 = cx + (x0 * 340) / depth;
            let py: i32 = cy + (y1 * 340) / depth;
            let mut b: i32 = 160 + z1;
            if b < 50 { b = 50; }
            if b > 255 { b = 255; }
            host::display::fill_rect(px, py, 2, 2, (b << 16) | (b << 8) | 255);
            lon = lon + 8;
        }
        lat = lat + 8;
    }
    host::display::present();
}
